def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    return np.where(rem >= 0, -rem, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    valid_mask = bins >= item
    item_count = bins // item
    leftover_space = bins % item
    priority_scores = item_count / (1 + leftover_space)
    return np.where(valid_mask, priority_scores, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    epsilon = 1e-12
    return np.where(rem >= 0, 1.0 / (np.abs(rem - 0.5 * item) + epsilon), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    epsilon = 1e-12
    utilization = (bins - rem) / bins
    utilization = np.where(bins > 0, utilization, 0)
    return np.where(rem >= 0, 1.0 / (np.abs(rem - 0.5 * item) + epsilon + 0.1 * utilization**2), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    return np.where(rem >= 0, -np.abs(rem - item), -np.inf)
